ground_truth:
def get_useful_review_stats(reviews, threshold=50):
    useful_reviews = [review for review in reviews if len(review['Comments']) > threshold]
    recommended = sum(1 for review in useful_reviews if review['Bottom Line'] == 'Yes, I would recommend this to a friend')
    return {'num_useful_reviews': len(useful_reviews), 'recommended': recommended, 'recommended_percentage': (recommended / len(useful_reviews)) * 100 if useful_reviews else 0}

